#include <stdio.h>

struct Point {
    int x, y;
};

void printPoint(const struct Point *p) {   // pointer avoids copying; const signals read-only
    printf("(%d, %d)\n", p->x, p->y);        // arrow operator through the pointer
}

int main() {
    struct Point p1 = {3, 4};
    printPoint(&p1);

    struct Point points[2] = { {0, 0}, {1, 1} };
    printPoint(&points[1]);
    return 0;
}
